import React, { useEffect, useState } from "react";

const AgentDownload = () => {
  const [userToken, setUserToken] = useState("");
  const [serverIP, setServerIP] = useState("");

  useEffect(() => {
    setUserToken(localStorage.getItem("userToken") || "YOUR_API_TOKEN");
    setServerIP(localStorage.getItem("serverIP") || "YOUR_SERVER_IP");
  }, []);

  return (
    <div>
      <h2>Download and Install the Monitoring Agent</h2>
      <p>Follow these steps to install the agent on your web server:</p>

      <h3>1. Download the Agent</h3>
      <p>Run this command in your server terminal:</p>
      <code>wget http://203.143.13.21:8000/static/agent.py</code>

      <h3>2. Install Dependencies</h3>
      <p>Ensure the required Python libraries are installed:</p>
      <code>pip install psutil requests</code>

      <h3>3. Run the Agent with Your API Key</h3>
      <p>Use this command to start monitoring your server:</p>
      <code>
        python agent.py --api-key {userToken} --server-ip {serverIP}
      </code>

      <h3>4. Verify Connection</h3>
      <p>Check your dashboard to ensure the metrics are being received.</p>

      <h3>Need Help?</h3>
      <p>If you encounter any issues, contact support at <a href="mailto:chameerahetti1998@gmail.com">chameerahetti1998@gmail.com</a></p>
    </div>
  );
};

export default AgentDownload;
